"""A service configured at deploy time rather than at build time.

Same shape as hello-http, with three values that arrive from the environment:

* ``GREETING``     — chosen by whoever deploys it, on the deploy form.
* ``ADMIN_TOKEN``  — generated by Musher. Nobody types it, and it is not in
                     this repository or in the image.
* ``BUILD_CHANNEL`` — fixed by the Component, the same for every deployment.

The point is that none of these required rebuilding the image. One image, many
configurations.
"""

from __future__ import annotations

import hmac
import json
import os
import signal
import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from types import FrameType

PORT = int(os.environ.get("PORT", "8080"))
GREETING = os.environ.get("GREETING", "Hello")
BUILD_CHANNEL = os.environ.get("BUILD_CHANNEL", "unset")
ADMIN_TOKEN = os.environ.get("ADMIN_TOKEN", "")


class Handler(BaseHTTPRequestHandler):
    def do_GET(self) -> None:  # noqa: N802 -- BaseHTTPRequestHandler's required name
        if self.path == "/healthz":
            self._respond(200, {"status": "ok"})
        elif self.path == "/":
            self._respond(200, {"message": GREETING, "channel": BUILD_CHANNEL})
        elif self.path == "/admin":
            self._admin()
        else:
            self._respond(404, {"error": "not found"})

    def _admin(self) -> None:
        """Gated by the token Musher generated at deploy time."""
        if not ADMIN_TOKEN:
            # Fail closed. An unset secret must never mean "open to everyone".
            self._respond(503, {"error": "admin token not configured"})
            return

        presented = self.headers.get("X-Admin-Token", "")
        # Constant-time: a plain == leaks the token one character at a time.
        if not hmac.compare_digest(presented, ADMIN_TOKEN):
            self._respond(401, {"error": "unauthorized"})
            return

        self._respond(200, {"greeting": GREETING, "channel": BUILD_CHANNEL})

    def _respond(self, status: int, payload: dict[str, str]) -> None:
        body = json.dumps(payload).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, fmt: str, *args: object) -> None:
        sys.stdout.write("%s - %s\n" % (self.address_string(), fmt % args))
        sys.stdout.flush()


def main() -> None:
    server = ThreadingHTTPServer(("0.0.0.0", PORT), Handler)  # noqa: S104 -- containers bind all interfaces

    def shutdown(_signum: int, _frame: FrameType | None) -> None:
        server.shutdown()

    signal.signal(signal.SIGTERM, shutdown)
    signal.signal(signal.SIGINT, shutdown)

    # Log whether the secret arrived, never the secret itself.
    sys.stdout.write(
        f"listening on :{PORT} channel={BUILD_CHANNEL} admin_token={'set' if ADMIN_TOKEN else 'MISSING'}\n"
    )
    sys.stdout.flush()
    server.serve_forever()


if __name__ == "__main__":
    main()
